function stripScrapedHeroSection(html: string): string {
  return html.replace(
    /<section class="relative overflow-hidden bg-gradient-to-br from-blue-900[\s\S]*?<\/section><\/div>/,
    "</div>",
  );
}

function stripDuplicateClientTestimonialsSection(html: string): string {
  // The homepage already renders the interactive `TestimonialCarousel` component.
  // This removes the legacy, static testimonial "carousel" baked into the HTML blob.
  return html.replace(
    /<section class="py-20 bg-gradient-to-br from-blue-900[\s\S]*?Trusted by Clients Across Kent[\s\S]*?<\/section>/g,
    "",
  );
}

function stripKentContactsSection(html: string): string {
  return html.replace(
    /<section class="py-16 bg-white" aria-labelledby="kent-contacts-heading">[\s\S]*?<\/section>/g,
    "",
  );
}

function stripDuplicateHomeCtaSection(html: string): string {
  return html.replace(
    /<section class="py-20 bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 relative overflow-hidden" aria-labelledby="cta-heading">[\s\S]*?<\/section>/g,
    "",
  );
}

/** Services cards now rendered by HomeServicesSection — drop scraped duplicate. */
function stripScrapedServicesGrid(html: string): string {
  return html.replace(
    /<div class="max-w-7xl mx-auto px-4"><div class="text-center mb-16">[\s\S]*?How we can help[\s\S]*?<\/div><\/div><\/div><\/div><\/section>/,
    "",
  );
}

/** Legacy purple testimonial carousel already covered by TestimonialCarousel. */
function stripPurpleTestimonialBlock(html: string): string {
  return html.replace(
    /<section class="py-20 bg-gradient-to-br from-blue-900 via-indigo-800 to-purple-900[\s\S]*?<\/section>/g,
    "",
  );
}

function fixStationAddresses(html: string): string {
  return html.replaceAll("Park Place, Dover", "Ladywell, Dover CT16 1DJ");
}

function improveBadgeContrast(html: string): string {
  return (
    html
      // Bright backgrounds + white text were failing contrast in Lighthouse/Bing previews.
      .replaceAll("bg-green-500 text-white", "bg-emerald-700 text-white")
      .replaceAll("hover:bg-green-400", "hover:bg-emerald-600")
      .replaceAll("bg-amber-500 text-white", "bg-amber-400 text-slate-900")
      .replaceAll("bg-purple-500 text-white", "bg-purple-700 text-white")
  );
}

